["İyi parti vermeyi hep biliyorsunuz! Vlad bunu görmeye geldiğine mutlu!"] = "İYİ PARTİ VERMEYİ HEP BİLİYORSUNUZ! VLAD BUNU GÖRMEYE GELDİĞİNE MUTLU!",
