["İşi biliyorsunuz: Daha fazla malzeme almak için helikoptere işaret verin. Ya da çıkıp gidin, size kalmış."] = "İŞİ BİLİYORSUNUZ: DAHA FAZLA MALZEME ALMAK İÇİN HELİKOPTERE İŞARET VERİN. YA DA ÇIKIP GİDİN, SİZE KALMIŞ.",
["İşi bitirmeye bu kadar yaklaşmışken sıçmayın. Macunu ızgaraya sürüp yakarak geçin yeter!"] = "İŞİ BİTİRMEYE BU KADAR YAKLAŞMIŞKEN SIÇMAYIN. MACUNU IZGARAYA SÜRÜP YAKARAK GEÇİN YETER!",
["İşi bitti! Çabuk, aşağıya, kasa dairesine!"] = "İŞİ BİTTİ! ÇABUK, AŞAĞIYA, KASA DAİRESİNE!",
["İşi doğru yaptıysanız gürültü çıkması sorun değil. Şimdi verileri araştırıyorum. Yarım veri tabanı biraz piyango gibi; umalım da şansımız yaver gitsin."] = "İŞİ DOĞRU YAPTIYSANIZ GÜRÜLTÜ ÇIKMASI SORUN DEĞİL. ŞİMDİ VERİLERİ ARAŞTIRIYORUM. YARIM VERİ TABANI BİRAZ PİYANGO GİBİ; UMALIM DA ŞANSIMIZ YAVER GİTSİN.",
["İşi hızlandırmak için halat kurun."] = "İŞİ HIZLANDIRMAK İÇİN HALAT KURUN.",
["İşi neredeyse bitti!"] = "İŞİ NEREDEYSE BİTTİ!",
["İşi sağlama almakta fayda var. Çıkmadan önce girişte taratın."] = "İŞİ SAĞLAMA ALMAKTA FAYDA VAR. ÇIKMADAN ÖNCE GİRİŞTE TARATIN.",
["İşi yap, vurgunu kap."] = "İŞİ YAP, VURGUNU KAP.",
["İşi yaptınız ama umduğum ustalıktan eser yoktu. Eve dönün ekip."] = "İŞİ YAPTINIZ AMA UMDUĞUM USTALIKTAN ESER YOKTU. EVE DÖNÜN EKİP.",
["İşim almak olabilir ama Vlad hiç karşılık vermez demeyin! Noel geldi amına koyayım!"] = "İŞİM ALMAK OLABİLİR AMA VLAD HİÇ KARŞILIK VERMEZ DEMEYİN! NOEL GELDİ AMINA KOYAYIM!",
["İşim, etkileyici bir bağlantı ağının temellerini atmama olanak sağladı."] = "İŞİM, ETKİLEYİCİ BİR BAĞLANTI AĞININ TEMELLERİNİ ATMAMA OLANAK SAĞLADI.",
["İşimiz bitince sizi çatıdan alacağım."] = "İŞİMİZ BİTİNCE SİZİ ÇATIDAN ALACAĞIM.",
["İşimiz bitti ekip. Gitme vakti."] = "İŞİMİZ BİTTİ EKİP. GİTME VAKTİ.",
["İşimiz bitti sevgili dostlarım! Herkes helikoptere!"] = "İŞİMİZ BİTTİ SEVGİLİ DOSTLARIM! HERKES HELİKOPTERE!",
["İşimiz bitti, hadi çıkalım!"] = "İŞİMİZ BİTTİ, HADİ ÇIKALIM!",
["İşimiz bitti, şimdi içeri girip o af belgelerini bulun!"] = "İŞİMİZ BİTTİ, ŞİMDİ İÇERİ GİRİP O AF BELGELERİNİ BULUN!",
["İşimiz bitti. Hazır olur olmaz gidebilirsiniz."] = "İŞİMİZ BİTTİ. HAZIR OLUR OLMAZ GİDEBİLİRSİNİZ.",
["İşimiz bitti. Şimdi kaçın! Vlad'ı nükleer bombalarıyla bırakın."] = "İŞİMİZ BİTTİ. ŞİMDİ KAÇIN! VLAD'I NÜKLEER BOMBALARIYLA BIRAKIN.",
["İşimiz bitti. Şu çılgın Ivan'ı nükleerleriyle bırakabilir ya da dönüp daha fazla ganimet alabilirsiniz."] = "İŞİMİZ BİTTİ. ŞU ÇILGIN IVAN'I NÜKLEERLERİYLE BIRAKABİLİR YA DA DÖNÜP DAHA FAZLA GANİMET ALABİLİRSİNİZ.",
["İşimize yarayabilecek şeyler için gözünüzü açık tutun."] = "İŞİMİZE YARAYABİLECEK ŞEYLER İÇİN GÖZÜNÜZÜ AÇIK TUTUN.",
["İşimizi yaptık, şimdi çıkın oradan!"] = "İŞİMİZİ YAPTIK, ŞİMDİ ÇIKIN ORADAN!",
["İşin aletleri, istediğiniz yere bırakılır."] = "İŞİN ALETLERİ, İSTEDİĞİNİZ YERE BIRAKILIR.",
["İşin yarısı tamam. İkinci Anahtar Kartı'nı bulun, Kasa Dairesi'ne yürüyüp girin."] = "İŞİN YARISI TAMAM. İKİNCİ ANAHTAR KARTI'NI BULUN, KASA DAİRESİ'NE YÜRÜYÜP GİRİN.",
["İşin zor kısmına geldik: B planı. İyi şanslar!"] = "İŞİN ZOR KISMINA GELDİK: B PLANI. İYİ ŞANSLAR!",
["İşin, polislerin depo tesisine girip daha sonra ihtiyacımız olacak erişim kodlarını aramak."] = "İŞİN, POLİSLERİN DEPO TESİSİNE GİRİP DAHA SONRA İHTİYACIMIZ OLACAK ERİŞİM KODLARINI ARAMAK.",
["İşindeki becerisini sanata dönüştürmekle övünen soyguncu veya tetikçi için bu kıyafet tam aranan şey olabilir. Geleneksel kesim ve gösterişsiz kumaşlar, en yeni taktik lif teknolojisiyle buluşuyor. Yağmura bile dayanır!"] = "İŞİNDEKİ BECERİSİNİ SANATA DÖNÜŞTÜRMEKLE ÖVÜNEN SOYGUNCU VEYA TETİKÇİ İÇİN BU KIYAFET TAM ARANAN ŞEY OLABİLİR. GELENEKSEL KESİM VE GÖSTERİŞSİZ KUMAŞLAR, EN YENİ TAKTİK LİF TEKNOLOJİSİYLE BULUŞUYOR. YAĞMURA BİLE DAYANIR!",
["İşiniz bitecek!"] = "İŞİNİZ BİTECEK!",
["İşiniz bitince balonu kaldırmanız yeter, havalı çocuklar!"] = "İŞİNİZ BİTİNCE BALONU KALDIRMANIZ YETER, HAVALI ÇOCUKLAR!",
