["İşiniz bitti dostlarım!"] = "İŞİNİZ BİTTİ DOSTLARIM!",
["İşiniz bitti, ayrılma vakti geldi. Hadi kımıldayın!"] = "İŞİNİZ BİTTİ, AYRILMA VAKTİ GELDİ. HADİ KIMILDAYIN!",
["İşiniz bitti, herkes toplansın!"] = "İŞİNİZ BİTTİ, HERKES TOPLANSIN!",
