["İşinizi bitirin, sonra gitme vakti. Tahliyeniz hazır."] = "İŞİNİZİ BİTİRİN, SONRA GİTME VAKTİ. TAHLİYENİZ HAZIR.",
["İşinizin bittiğini, hazır olduğunuzu varsayıyorum, öyle mi?"] = "İŞİNİZİN BİTTİĞİNİ, HAZIR OLDUĞUNUZU VARSAYIYORUM, ÖYLE Mİ?",
