["İşte başladık yine..."] = "İŞTE BAŞLADIK YİNE...",
["İşte başlıyoruz dostlar. Bu Bain için, tamam mı?"] = "İŞTE BAŞLIYORUZ DOSTLAR. BU BAIN İÇİN, TAMAM MI?",
["İşte başlıyoruz sevgili dostlar. Aradığımız af belgeleri büyük ihtimalle Beyaz Saray'ın altındaki Başkanlık Acil Durum Operasyon Merkezi'nde, yani PEOC'ta tutuluyor. Kesin ayrıntıları alamadım. Güvenliği ciddi biçimde artırmışlar gibi, duruma göre hareket etmeliyiz. Sizi bizzat ben uçuracağım. Biraz aralarına karışabilmeniz için Murky üniformaları giyeceksiniz. Mümkünse sessizce girin, gerçekten gerekirse gürültü koparın. Bu Bain için. Belki bizim için de, ha?"] = "İŞTE BAŞLIYORUZ SEVGİLİ DOSTLAR. ARADIĞIMIZ AF BELGELERİ BÜYÜK İHTİMALLE BEYAZ SARAY'IN ALTINDAKİ BAŞKANLIK ACİL DURUM OPERASYON MERKEZİ'NDE, YANİ PEOC'TA TUTULUYOR. KESİN AYRINTILARI ALAMADIM. GÜVENLİĞİ CİDDİ BİÇİMDE ARTIRMIŞLAR GİBİ, DURUMA GÖRE HAREKET ETMELİYİZ. SİZİ BİZZAT BEN UÇURACAĞIM. BİRAZ ARALARINA KARIŞABİLMENİZ İÇİN MURKY ÜNİFORMALARI GİYECEKSİNİZ. MÜMKÜNSE SESSİZCE GİRİN, GERÇEKTEN GEREKİRSE GÜRÜLTÜ KOPARIN. BU BAIN İÇİN. BELKİ BİZİM İÇİN DE, HA?",
["İşte başlıyoruz!"] = "İŞTE BAŞLIYORUZ!",
["İşte başlıyoruz, bu işi görür."] = "İŞTE BAŞLIYORUZ, BU İŞİ GÖRÜR.",
["İşte başlıyoruz. Birkaç dakikaya deler geçeriz."] = "İŞTE BAŞLIYORUZ. BİRKAÇ DAKİKAYA DELER GEÇERİZ.",
["İşte başlıyoruz. Kapılar açıldı! Bakalım ne kadar zenginiz."] = "İŞTE BAŞLIYORUZ. KAPILAR AÇILDI! BAKALIM NE KADAR ZENGİNİZ.",
["İşte başlıyoruz... işte... başlı... yoruuuz!"] = "İŞTE BAŞLIYORUZ... İŞTE... BAŞLI... YORUUUZ!",
["İşte beklediğin bu. Şu kendini beğenmiş Taser’lardan tatlı, elektrikli intikamını al. Al sana yıldırım!"] = "İŞTE BEKLEDİĞİN BU. ŞU KENDİNİ BEĞENMİŞ TASER’LARDAN TATLI, ELEKTRİKLİ İNTİKAMINI AL. AL SANA YILDIRIM!",
["İşte benim çocuklarım! Harika!"] = "İŞTE BENİM ÇOCUKLARIM! HARİKA!",
["İşte bir hediye! Teşekkürler, güzel ağaç!"] = "İŞTE BİR HEDİYE! TEŞEKKÜRLER, GÜZEL AĞAÇ!",
["İşte bir pürüz daha. Kasa dairesine elektrik veriyorlar!"] = "İŞTE BİR PÜRÜZ DAHA. KASA DAİRESİNE ELEKTRİK VERİYORLAR!",
["İşte bir şey var. Hadi alın!"] = "İŞTE BİR ŞEY VAR. HADİ ALIN!",
["İşte biz böyle yaparız! İyi iş millet. Şimdi değirmene girin."] = "İŞTE BİZ BÖYLE YAPARIZ! İYİ İŞ MİLLET. ŞİMDİ DEĞİRMENE GİRİN.",
["İşte bu amına koyayım!"] = "İŞTE BU AMINA KOYAYIM!",
["İşte bu amına koyayım. Bu benim."] = "İŞTE BU AMINA KOYAYIM. BU BENİM.",
["İşte bu bayanlar baylar. İŞ. TAMAM. Şimdi buradan siktir olup gitmem gerekiyor!"] = "İŞTE BU BAYANLAR BAYLAR. İŞ. TAMAM. ŞİMDİ BURADAN SİKTİR OLUP GİTMEM GEREKİYOR!",
["İşte bu be, dostlarım. Tamam, Kasa Dairesi yeniden açılıyor. Güzel!"] = "İŞTE BU BE, DOSTLARIM. TAMAM, KASA DAİRESİ YENİDEN AÇILIYOR. GÜZEL!",
["İşte bu be."] = "İŞTE BU BE.",
["İşte bu be. Daha bitirmedik."] = "İŞTE BU BE. DAHA BİTİRMEDİK.",
["İşte bu dostlarım. Çabucak dönüp kapıdan geçin, olur mu?"] = "İŞTE BU DOSTLARIM. ÇABUCAK DÖNÜP KAPIDAN GEÇİN, OLUR MU?",
["İşte bu ekip, artık sadece çatı kaldı."] = "İŞTE BU EKİP, ARTIK SADECE ÇATI KALDI.",
["İşte bu ekip. Ellerinde ne varsa bu işe sürüyorlar. Çıkın oradan!"] = "İŞTE BU EKİP. ELLERİNDE NE VARSA BU İŞE SÜRÜYORLAR. ÇIKIN ORADAN!",
["İşte bu ekip. Tarama odasındaki gaz sorunu çözülmüş olmalı."] = "İŞTE BU EKİP. TARAMA ODASINDAKİ GAZ SORUNU ÇÖZÜLMÜŞ OLMALI.",
["İşte bu millet, başarıyoruz. Bir saniye. \"Hey Bile, C4 zamanı geldi. Ne kadar çabuk gelirsin?\""] = "İŞTE BU MİLLET, BAŞARIYORUZ. BİR SANİYE. \"HEY BILE, C4 ZAMANI GELDİ. NE KADAR ÇABUK GELİRSİN?\"",
["İşte bu millet, işte bu. Hey Locke, altını unutmadın, değil mi?"] = "İŞTE BU MİLLET, İŞTE BU. HEY LOCKE, ALTINI UNUTMADIN, DEĞİL Mİ?",
["İşte bu millet. Bir banka işi daha. Soyguncu hayatının ekmek kapısı. Bu sefer Roberts Bank'in bir şubesini vuruyoruz. Kaynaklarım, güzel bir sevkiyat alacaklarını ya da yeni aldıklarını söylüyor. Bir ziyaret edelim."] = "İŞTE BU MİLLET. BİR BANKA İŞİ DAHA. SOYGUNCU HAYATININ EKMEK KAPISI. BU SEFER ROBERTS BANK'İN BİR ŞUBESİNİ VURUYORUZ. KAYNAKLARIM, GÜZEL BİR SEVKİYAT ALACAKLARINI YA DA YENİ ALDIKLARINI SÖYLÜYOR. BİR ZİYARET EDELİM.",
["İşte bu millet. Biraz sürecek. Elektrik kesilmesin yeter."] = "İŞTE BU MİLLET. BİRAZ SÜRECEK. ELEKTRİK KESİLMESİN YETER.",
["İşte bu millet. Uçaksavar devre dışı kaldı. Ama bir tane daha var."] = "İŞTE BU MİLLET. UÇAKSAVAR DEVRE DIŞI KALDI. AMA BİR TANE DAHA VAR.",
["İşte bu millet. Vlad mesajını iletecek. Paramızı alalım."] = "İŞTE BU MİLLET. VLAD MESAJINI İLETECEK. PARAMIZI ALALIM.",
["İşte bu millet. Şimdi trenlere dönüp EMP bombasını ele geçirin."] = "İŞTE BU MİLLET. ŞİMDİ TRENLERE DÖNÜP EMP BOMBASINI ELE GEÇİRİN.",
["İşte bu! Aradığımız şey bu."] = "İŞTE BU! ARADIĞIMIZ ŞEY BU.",
["İşte bu! Aradığımız şey bu. Matkabı şimdi yolluyorum."] = "İŞTE BU! ARADIĞIMIZ ŞEY BU. MATKABI ŞİMDİ YOLLUYORUM.",
["İşte bu! Artık Vlad'la uğraşmamaları gerektiğini biliyorlar."] = "İŞTE BU! ARTIK VLAD'LA UĞRAŞMAMALARI GEREKTİĞİNİ BİLİYORLAR.",
["İşte bu! Commissar'ın yerini bulduk. Kıçımızı kaldırma vakti. O sandıklar aklıma bir fikir getirdi..."] = "İŞTE BU! COMMİSSAR'IN YERİNİ BULDUK. KIÇIMIZI KALDIRMA VAKTİ. O SANDIKLAR AKLIMA BİR FİKİR GETİRDİ...",
["İşte bu! EMP işini yaptı! Şimdi kapaktan laboratuvara girin."] = "İŞTE BU! EMP İŞİNİ YAPTI! ŞİMDİ KAPAKTAN LABORATUVARA GİRİN.",
["İşte bu! Gitme vakti! Hâlâ formdasın Dallas!"] = "İŞTE BU! GİTME VAKTİ! HÂLÂ FORMDASIN DALLAS!",
["İşte bu! Harika iş ekip."] = "İŞTE BU! HARİKA İŞ EKİP.",
["İşte bu! Kasa dairesi açıldı. Parayı çantalamaya başlayın! "] = "İŞTE BU! KASA DAİRESİ AÇILDI. PARAYI ÇANTALAMAYA BAŞLAYIN! ",
["İşte bu! Keçiler bizde, kokain bizde! Şıkır şıkır para, amına koyayım dostlarım! Şimdi, kim bize köri yemeye gelmek ister?"] = "İŞTE BU! KEÇİLER BİZDE, KOKAİN BİZDE! ŞIKIR ŞIKIR PARA, AMINA KOYAYIM DOSTLARIM! ŞİMDİ, KİM BİZE KÖRİ YEMEYE GELMEK İSTER?",
["İşte bu! O füzeler tam aradığımız şey. Radara götürün. "] = "İŞTE BU! O FÜZELER TAM ARADIĞIMIZ ŞEY. RADARA GÖTÜRÜN. ",
["İşte bu! O trenler hiçbir yere gitmiyor. İyi hamle millet."] = "İŞTE BU! O TRENLER HİÇBİR YERE GİTMİYOR. İYİ HAMLE MİLLET.",
["İşte bu! Oldu! Ah, kusura bakmayın dostlarım... Biraz kendimi kaptırdım. "] = "İŞTE BU! OLDU! AH, KUSURA BAKMAYIN DOSTLARIM... BİRAZ KENDİMİ KAPTIRDIM. ",
["İşte bu! Paraya çevirme vakti bebeğim!"] = "İŞTE BU! PARAYA ÇEVİRME VAKTİ BEBEĞİM!",
["İşte bu! Tamamdır."] = "İŞTE BU! TAMAMDIR.",
["İşte bu! Tarama tamamlandı. Aferin millet."] = "İŞTE BU! TARAMA TAMAMLANDI. AFERİN MİLLET.",
["İşte bu! Çılgıncaydı ekip! Şimdi içeri girin."] = "İŞTE BU! ÇILGINCAYDI EKİP! ŞİMDİ İÇERİ GİRİN.",
["İşte bu! İndiriliyor. Biraz bekleyin."] = "İŞTE BU! İNDİRİLİYOR. BİRAZ BEKLEYİN.",
["İşte bu! İŞTE BU!"] = "İŞTE BU! İŞTE BU!",
["İşte bu! Şifreyi panik odasına götürün!"] = "İŞTE BU! ŞİFREYİ PANİK ODASINA GÖTÜRÜN!",
["İşte bu! Şimdi C4'ü yeraltı garajına yerleştirin. İçerideki adamımız, Kasa Dairesi'nin altındaki tavanı işaretledi. C4'ü oraya koyacaksınız."] = "İŞTE BU! ŞİMDİ C4'Ü YERALTI GARAJINA YERLEŞTİRİN. İÇERİDEKİ ADAMIMIZ, KASA DAİRESİ'NİN ALTINDAKİ TAVANI İŞARETLEDİ. C4'Ü ORAYA KOYACAKSINIZ.",
["İşte bu! Şimdi Kasa Dairesi üzerinde çalıştıralım."] = "İŞTE BU! ŞİMDİ KASA DAİRESİ ÜZERİNDE ÇALIŞTIRALIM.",
["İşte bu! Şimdi bütün keçileri içine koyun!"] = "İŞTE BU! ŞİMDİ BÜTÜN KEÇİLERİ İÇİNE KOYUN!",
["İşte bu! Şimdi geçmişini araştırıyorum. Bekleyin."] = "İŞTE BU! ŞİMDİ GEÇMİŞİNİ ARAŞTIRIYORUM. BEKLEYİN.",
["İşte bu! Şimdi gidiyorum!"] = "İŞTE BU! ŞİMDİ GİDİYORUM!",
["İşte bu! Şimdi oradan sağ çıkmaya bakın."] = "İŞTE BU! ŞİMDİ ORADAN SAĞ ÇIKMAYA BAKIN.",
["İşte bu! Şimdi çıkarın da bu işi bitirelim!"] = "İŞTE BU! ŞİMDİ ÇIKARIN DA BU İŞİ BİTİRELİM!",
["İşte bu! Şu Rus bebek zımbırtılarından biri gibi. Kutuyu alın, güvende tutun."] = "İŞTE BU! ŞU RUS BEBEK ZIMBIRTILARINDAN BİRİ GİBİ. KUTUYU ALIN, GÜVENDE TUTUN.",
["İşte bu, aferin. Kasa dairesinin koruması kalkmış olmalı; sistem kırma işlemine devam edebilirsiniz."] = "İŞTE BU, AFERİN. KASA DAİRESİNİN KORUMASI KALKMIŞ OLMALI; SİSTEM KIRMA İŞLEMİNE DEVAM EDEBİLİRSİNİZ.",
["İşte bu, alarm kapandı. Şimdi o kapıyı açın."] = "İŞTE BU, ALARM KAPANDI. ŞİMDİ O KAPIYI AÇIN.",
["İşte bu, artık geçebilirsiniz."] = "İŞTE BU, ARTIK GEÇEBİLİRSİNİZ.",
["İşte bu, açıldı! Aşağı inin! "] = "İŞTE BU, AÇILDI! AŞAĞI İNİN! ",
["İşte bu, açın."] = "İŞTE BU, AÇIN.",
["İşte bu, buradan defolup gitme vakti."] = "İŞTE BU, BURADAN DEFOLUP GİTME VAKTİ.",
["İşte bu, değil mi? Alıp devam edin."] = "İŞTE BU, DEĞİL Mİ? ALIP DEVAM EDİN.",
["İşte bu, değil mi? Tamam dostlar. Kilidi kırmak için kablo kutularındaki doğru kabloları kesmelisiniz."] = "İŞTE BU, DEĞİL Mİ? TAMAM DOSTLAR. KİLİDİ KIRMAK İÇİN KABLO KUTULARINDAKİ DOĞRU KABLOLARI KESMELİSİNİZ.",
["İşte bu, işiniz bitti."] = "İŞTE BU, İŞİNİZ BİTTİ.",
["İşte bu, işte bu. Gidin. Gidin!"] = "İŞTE BU, İŞTE BU. GİDİN. GİDİN!",
["İşte bu, işte bu. Koşun. Koşun!"] = "İŞTE BU, İŞTE BU. KOŞUN. KOŞUN!",
["İşte bu, kapılar tamam. Tablolar üzerinde hâlâ çalışıyorum."] = "İŞTE BU, KAPILAR TAMAM. TABLOLAR ÜZERİNDE HÂLÂ ÇALIŞIYORUM.",
["İşte bu, orada. Kapıyı açıp BCI başlığıyla yazılımı güvene alın."] = "İŞTE BU, ORADA. KAPIYI AÇIP BCI BAŞLIĞIYLA YAZILIMI GÜVENE ALIN.",
["İşte bu, şimdi gidip o güzel taşları almanız kaldı, ha?"] = "İŞTE BU, ŞİMDİ GİDİP O GÜZEL TAŞLARI ALMANIZ KALDI, HA?",
["İşte bu. Aferin! Kasa dairesi yeniden açılıyor!"] = "İŞTE BU. AFERİN! KASA DAİRESİ YENİDEN AÇILIYOR!",
["İşte bu. Ahhhhh, neredeyse baştan çıkıyorum. Gün batımında iki güneş görmek. Büyüleyici."] = "İŞTE BU. AHHHHH, NEREDEYSE BAŞTAN ÇIKIYORUM. GÜN BATIMINDA İKİ GÜNEŞ GÖRMEK. BÜYÜLEYİCİ.",
["İşte bu. Açın da bakalım ne var."] = "İŞTE BU. AÇIN DA BAKALIM NE VAR.",
["İşte bu. Açın da bakalım ne varmış."] = "İŞTE BU. AÇIN DA BAKALIM NE VARMIŞ.",
["İşte bu. Baskı kalıpları o vagonlarda olmalı."] = "İŞTE BU. BASKI KALIPLARI O VAGONLARDA OLMALI.",
["İşte bu. Bu bebeği buradan kaldırmaya hazırım."] = "İŞTE BU. BU BEBEĞİ BURADAN KALDIRMAYA HAZIRIM.",
["İşte bu. Bu istihbarat beni doğrudan Esteban'ın işverenine götürecek, onlar da hak ettiklerini bulacak. Güzel iş. Size borçluyum."] = "İŞTE BU. BU İSTİHBARAT BENİ DOĞRUDAN ESTEBAN'IN İŞVERENİNE GÖTÜRECEK, ONLAR DA HAK ETTİKLERİNİ BULACAK. GÜZEL İŞ. SİZE BORÇLUYUM.",
["İşte bu. Commissar öldü. Hoxton'ı geri almaya bir adım daha yaklaştık. Helikopter gönderiyorum, yerinizde kalın. Yukarıda iyi iş çıkardınız."] = "İŞTE BU. COMMİSSAR ÖLDÜ. HOXTON'I GERİ ALMAYA BİR ADIM DAHA YAKLAŞTIK. HELİKOPTER GÖNDERİYORUM, YERİNİZDE KALIN. YUKARIDA İYİ İŞ ÇIKARDINIZ.",
["İşte bu. Güzel! Sizi bekliyorum."] = "İŞTE BU. GÜZEL! SİZİ BEKLİYORUM.",
["İşte bu. Harika! Şimdi Hoxton'a geri götürün."] = "İŞTE BU. HARİKA! ŞİMDİ HOXTON'A GERİ GÖTÜRÜN.",
["İşte bu. Kalıp daha fazlasını alın ya da çıkın. Size kalmış."] = "İŞTE BU. KALIP DAHA FAZLASINI ALIN YA DA ÇIKIN. SİZE KALMIŞ.",
["İşte bu. Kasa dairesine götürün. Bu işi zor yoldan yapalım."] = "İŞTE BU. KASA DAİRESİNE GÖTÜRÜN. BU İŞİ ZOR YOLDAN YAPALIM.",
["İşte bu. Kasa'yı açın."] = "İŞTE BU. KASA'YI AÇIN.",
["İşte bu. O terminali hackleyin."] = "İŞTE BU. O TERMİNALİ HACKLEYİN.",
["İşte bu. Taret bizde. Şimdi sadece mühimmat gerekiyor."] = "İŞTE BU. TARET BİZDE. ŞİMDİ SADECE MÜHİMMAT GEREKİYOR.",
["İşte bu. Çatıya çıkıp sizi almaları için bir işaret fişeği yakın."] = "İŞTE BU. ÇATIYA ÇIKIP SİZİ ALMALARI İÇİN BİR İŞARET FİŞEĞİ YAKIN.",
["İşte bu. Şimdi dördüncü ve beşinci kattan biraz daha lazım."] = "İŞTE BU. ŞİMDİ DÖRDÜNCÜ VE BEŞİNCİ KATTAN BİRAZ DAHA LAZIM.",
["İşte bu. Şimdi gidip o dizüstünü bulun ve sistemine sızın."] = "İŞTE BU. ŞİMDİ GİDİP O DİZÜSTÜNÜ BULUN VE SİSTEMİNE SIZIN.",
["İşte bu. Şimdi parçaları oradan çıkarın."] = "İŞTE BU. ŞİMDİ PARÇALARI ORADAN ÇIKARIN.",
["İşte bu. Şimdi pilotun haber vermesini bekleyin."] = "İŞTE BU. ŞİMDİ PİLOTUN HABER VERMESİNİ BEKLEYİN.",
["İşte bu. Şimdi taramaya başlayabiliriz."] = "İŞTE BU. ŞİMDİ TARAMAYA BAŞLAYABİLİRİZ.",
["İşte bu. Şimdiye kadarki en büyük banka soygunu. Her şey bu anın hazırlığıydı. Ne yapacağınızı biliyorsunuz."] = "İŞTE BU. ŞİMDİYE KADARKİ EN BÜYÜK BANKA SOYGUNU. HER ŞEY BU ANIN HAZIRLIĞIYDI. NE YAPACAĞINIZI BİLİYORSUNUZ.",
["İşte bu... her neyse! Tamam, bırakma noktası bir depo odası. Oraya götürüp güvenceye alın."] = "İŞTE BU... HER NEYSE! TAMAM, BIRAKMA NOKTASI BİR DEPO ODASI. ORAYA GÖTÜRÜP GÜVENCEYE ALIN.",
["İşte buna güzel delik derim!"] = "İŞTE BUNA GÜZEL DELİK DERİM!",
["İşte buna vurgun denir. Silip süpürün ekip."] = "İŞTE BUNA VURGUN DENİR. SİLİP SÜPÜRÜN EKİP.",
["İşte bunlar sadece paranın getireceği şeyler. Bir yaşam tarzı, anlıyor musun?"] = "İŞTE BUNLAR SADECE PARANIN GETİRECEĞİ ŞEYLER. BİR YAŞAM TARZI, ANLIYOR MUSUN?",
["İşte bunlar! Şimdi Hoxton'a geri götürün."] = "İŞTE BUNLAR! ŞİMDİ HOXTON'A GERİ GÖTÜRÜN.",
["İşte burada! Bomba parçalarını teslim noktasına götürün!"] = "İŞTE BURADA! BOMBA PARÇALARINI TESLİM NOKTASINA GÖTÜRÜN!",
["İşte burada. Alın!"] = "İŞTE BURADA. ALIN!",
["İşte burada. The Golden Grin Casino."] = "İŞTE BURADA. THE GOLDEN GRIN CASINO.",
["İşte buradasın, küçük piç!"] = "İŞTE BURADASIN, KÜÇÜK PİÇ!",
["İşte buradasın, seni piç!"] = "İŞTE BURADASIN, SENİ PİÇ!",
["İşte buradayım!"] = "İŞTE BURADAYIM!",
["İşte burası dostlarım. Kesip geçmek için iyi bir nokta."] = "İŞTE BURASI DOSTLARIM. KESİP GEÇMEK İÇİN İYİ BİR NOKTA.",
["İşte burası ekip. Chavez'in mekânı."] = "İŞTE BURASI EKİP. CHAVEZ'İN MEKÂNI.",
["İşte burası millet... Bu banka, Mendoza ailesinin sınırın kuzeyindeki bütün sermayesini tutuyor. Küçük ihtiyar nineler her gün onların kanlı parasının yanından geçip gidiyor. Hector'ın dediği gibi, göz önünde gizlenmiş. En az $100m tutarında kirli para. İçeri girecek, kalabalığı kontrol altına alacak ve alarm çalmadan kasa dairesine gireceksiniz. Sonra parayı ateşe verip kendinizi videoya çekeceksiniz. Hector böyle istiyor."] = "İŞTE BURASI MİLLET... BU BANKA, MENDOZA AİLESİNİN SINIRIN KUZEYİNDEKİ BÜTÜN SERMAYESİNİ TUTUYOR. KÜÇÜK İHTİYAR NİNELER HER GÜN ONLARIN KANLI PARASININ YANINDAN GEÇİP GİDİYOR. HECTOR'IN DEDİĞİ GİBİ, GÖZ ÖNÜNDE GİZLENMİŞ. EN AZ $100M TUTARINDA KİRLİ PARA. İÇERİ GİRECEK, KALABALIĞI KONTROL ALTINA ALACAK VE ALARM ÇALMADAN KASA DAİRESİNE GİRECEKSİNİZ. SONRA PARAYI ATEŞE VERİP KENDİNİZİ VİDEOYA ÇEKECEKSİNİZ. HECTOR BÖYLE İSTİYOR.",
["İşte burası millet... Bu banka, Mendoza'ların sınırın kuzeyindeki bütün sermayesini tutuyor."] = "İŞTE BURASI MİLLET... BU BANKA, MENDOZA'LARIN SINIRIN KUZEYİNDEKİ BÜTÜN SERMAYESİNİ TUTUYOR.",
["İşte burası, gizli manevra sahası. Fırsatı değerlendirip bölgeyi keşfedin. Murky'ler ve kameralarla sıkı korunuyor, hata yapma lüksümüz yok."] = "İŞTE BURASI, GİZLİ MANEVRA SAHASI. FIRSATI DEĞERLENDİRİP BÖLGEYİ KEŞFEDİN. MURKY'LER VE KAMERALARLA SIKI KORUNUYOR, HATA YAPMA LÜKSÜMÜZ YOK.",
["İşte burası. Commissar'ın dairesi. Geçin."] = "İŞTE BURASI. COMMİSSAR'IN DAİRESİ. GEÇİN.",
["İşte burası. Her adımda sana yol göstereceğim."] = "İŞTE BURASI. HER ADIMDA SANA YOL GÖSTERECEĞİM.",
["İşte burası. Kenara çekin."] = "İŞTE BURASI. KENARA ÇEKİN.",
