["İşte burası. McKendrick müzesi. Paha biçilmez bir elmasın evi. Başlayalım."] = "İŞTE BURASI. MCKENDRİCK MÜZESİ. PAHA BİÇİLMEZ BİR ELMASIN EVİ. BAŞLAYALIM.",
["İşte burası. Tamam, o sunuculara erişmem lazım. Odayı temizleyin!"] = "İŞTE BURASI. TAMAM, O SUNUCULARA ERİŞMEM LAZIM. ODAYI TEMİZLEYİN!",
["İşte burası. Triad'ın paravan olarak kullandığı, bize söylenen çay dükkânı."] = "İŞTE BURASI. TRİAD'IN PARAVAN OLARAK KULLANDIĞI, BİZE SÖYLENEN ÇAY DÜKKÂNI.",
["İşte buydu. Güzeeel."] = "İŞTE BUYDU. GÜZEEEL.",
["İşte böyle dostlar! Şimdi o kasa dairesinin içine bakın!"] = "İŞTE BÖYLE DOSTLAR! ŞİMDİ O KASA DAİRESİNİN İÇİNE BAKIN!",
