["İşte böyle, tamam."] = "İŞTE BÖYLE, TAMAM.",
["İşte böyle, tıpkı filmlerdeki gibi. "] = "İŞTE BÖYLE, TIPKI FİLMLERDEKİ GİBİ. ",
