["İşte böyle. Şimdi kasa dairesinin bulunduğu odaya bir bakın, olur mu?"] = "İŞTE BÖYLE. ŞİMDİ KASA DAİRESİNİN BULUNDUĞU ODAYA BİR BAKIN, OLUR MU?",
["İşte böyle. Şimdi pilotun haber vermesini bekleyin."] = "İŞTE BÖYLE. ŞİMDİ PİLOTUN HABER VERMESİNİ BEKLEYİN.",
["İşte böyle. Şunu minibüse götürün!"] = "İŞTE BÖYLE. ŞUNU MİNİBÜSE GÖTÜRÜN!",
["İşte ev. Esteban'ın ofisi içeride bir yerde."] = "İŞTE EV. ESTEBAN'IN OFİSİ İÇERİDE BİR YERDE.",
["İşte fark edilmek, gösterişli bir izlenim bırakmak mı istiyorsun? Evet, yolu bu."] = "İŞTE FARK EDİLMEK, GÖSTERİŞLİ BİR İZLENİM BIRAKMAK MI İSTİYORSUN? EVET, YOLU BU.",
["İşte geldik! Matkapla açmanız gerekecek."] = "İŞTE GELDİK! MATKAPLA AÇMANIZ GEREKECEK.",
["İşte geldik! Ne bulabileceğinize bakın!"] = "İŞTE GELDİK! NE BULABİLECEĞİNİZE BAKIN!",
["İşte geldik. İşe dönme vakti. İyi hissettiriyor, değil mi?"] = "İŞTE GELDİK. İŞE DÖNME VAKTİ. İYİ HİSSETTİRİYOR, DEĞİL Mİ?",
["İşte geldik; hesaplaşma zamanı. Soyguncu ailemiz, sınırını henüz görmediğimiz bir güce karşı. Tek bir şey biliyorum: Ya buradan birlikte çıkacağız ya da denerken öleceğiz. Biz Palyaçolarız, hırsızlığın lanet tanrılarıyız ve kendi kurallarımızla oynarız. O yüzden sırada ne olursa olsun altın bir ihtişamla parlamaya hazırız."] = "İŞTE GELDİK; HESAPLAŞMA ZAMANI. SOYGUNCU AİLEMİZ, SINIRINI HENÜZ GÖRMEDİĞİMİZ BİR GÜCE KARŞI. TEK BİR ŞEY BİLİYORUM: YA BURADAN BİRLİKTE ÇIKACAĞIZ YA DA DENERKEN ÖLECEĞİZ. BİZ PALYAÇOLARIZ, HIRSIZLIĞIN LANET TANRILARIYIZ VE KENDİ KURALLARIMIZLA OYNARIZ. O YÜZDEN SIRADA NE OLURSA OLSUN ALTIN BİR İHTİŞAMLA PARLAMAYA HAZIRIZ.",
["İşte geldiler!"] = "İŞTE GELDİLER!",
["İşte geliyor!"] = "İŞTE GELİYOR!",
["İşte geliyor. Oda..."] = "İŞTE GELİYOR. ODA...",
["İşte geliyor. ‘BFD’. ‘Big Goddamn Drill’, yani ‘Kocaman Lanet Matkap’ demek. Sayılır."] = "İŞTE GELİYOR. ‘BFD’. ‘BİG GODDAMN DRİLL’, YANİ ‘KOCAMAN LANET MATKAP’ DEMEK. SAYILIR.",
["İşte geliyorlar! Ağızlarına sıçın!"] = "İŞTE GELİYORLAR! AĞIZLARINA SIÇIN!",
["İşte geliyorlar! Bir polis dalgası yaklaşıyor!"] = "İŞTE GELİYORLAR! BİR POLİS DALGASI YAKLAŞIYOR!",
["İşte geliyorlar, hazır olun."] = "İŞTE GELİYORLAR, HAZIR OLUN.",
["İşte geri sayım. Şimdi alarmı bulun! Devreye girmeden etkisiz hâle getirin."] = "İŞTE GERİ SAYIM. ŞİMDİ ALARMI BULUN! DEVREYE GİRMEDEN ETKİSİZ HÂLE GETİRİN.",
["İşte gerçek anı. Lokomotifimizi taşımak için vinci kullanın. Şu kıskaçlı oyuncak makinelerinden biriymiş gibi düşünün! Sadece daha büyük! Ve çok daha fazla şey tehlikede!"] = "İŞTE GERÇEK ANI. LOKOMOTİFİMİZİ TAŞIMAK İÇİN VİNCİ KULLANIN. ŞU KISKAÇLI OYUNCAK MAKİNELERİNDEN BİRİYMİŞ GİBİ DÜŞÜNÜN! SADECE DAHA BÜYÜK! VE ÇOK DAHA FAZLA ŞEY TEHLİKEDE!",
["İşte gidiyor. Unutmayın, sürat teknesi değil bu. Biraz sürecek. Göze batmayın. Alarmı tetiklememeye dikkat edin. Ya da fazladan ganimet arayın. Seçim sizin millet."] = "İŞTE GİDİYOR. UNUTMAYIN, SÜRAT TEKNESİ DEĞİL BU. BİRAZ SÜRECEK. GÖZE BATMAYIN. ALARMI TETİKLEMEMEYE DİKKAT EDİN. YA DA FAZLADAN GANİMET ARAYIN. SEÇİM SİZİN MİLLET.",
["İşte gidiyor. Uçak şimdi yolda."] = "İŞTE GİDİYOR. UÇAK ŞİMDİ YOLDA.",
["İşte hapisten kaçış böyle olur, dostlarım!"] = "İŞTE HAPİSTEN KAÇIŞ BÖYLE OLUR, DOSTLARIM!",
["İşte harika ganimetin ilki! Mükemmel! Şimdi yakında büyük bir dikey boşluk bulacaksınız. Ganimeti kabloyla yukarı gönderin. Ben göz kulak olurum."] = "İŞTE HARİKA GANİMETİN İLKİ! MÜKEMMEL! ŞİMDİ YAKINDA BÜYÜK BİR DİKEY BOŞLUK BULACAKSINIZ. GANİMETİ KABLOYLA YUKARI GÖNDERİN. BEN GÖZ KULAK OLURUM.",
["İşte helikopter geliyor!"] = "İŞTE HELİKOPTER GELİYOR!",
["İşte hidro havuz coşkusu. Ganimeti alın!"] = "İŞTE HİDRO HAVUZ COŞKUSU. GANİMETİ ALIN!",
["İşte hortum! Kasa dairesine bağlayın."] = "İŞTE HORTUM! KASA DAİRESİNE BAĞLAYIN.",
["İşte ileri teknoloji, çok değerli bir askerî canavar."] = "İŞTE İLERİ TEKNOLOJİ, ÇOK DEĞERLİ BİR ASKERÎ CANAVAR.",
["İşte işaretimiz! Tekneye geri dönün!"] = "İŞTE İŞARETİMİZ! TEKNEYE GERİ DÖNÜN!",
["İşte kaliteli petrol böyle olur!"] = "İŞTE KALİTELİ PETROL BÖYLE OLUR!",
["İşte kapak! Onunla ilgili bir fikrim var. Bile Noel Baba olacak; siz de çok uslu çocuklar olduğunuza göre..."] = "İŞTE KAPAK! ONUNLA İLGİLİ BİR FİKRİM VAR. BILE NOEL BABA OLACAK; SİZ DE ÇOK USLU ÇOCUKLAR OLDUĞUNUZA GÖRE...",
["İşte kapının ikinci kontrol odası."] = "İŞTE KAPININ İKİNCİ KONTROL ODASI.",
["İşte kaçış aracınız. Bütün ganimeti yükledikten sonra yakıt doldurmanız gerekiyor. "] = "İŞTE KAÇIŞ ARACINIZ. BÜTÜN GANİMETİ YÜKLEDİKTEN SONRA YAKIT DOLDURMANIZ GEREKİYOR. ",
["İşte klasik sürüm bu. Gerçekten kendini belli eden."] = "İŞTE KLASİK SÜRÜM BU. GERÇEKTEN KENDİNİ BELLİ EDEN.",
["İşte kod. 1138."] = "İŞTE KOD. 1138.",
["İşte lanet polisler geliyor!"] = "İŞTE LANET POLİSLER GELİYOR!",
["İşte o an geldi. Matkabı çalıştırır çalıştırmaz, olabildiğince hızlı tekneye dönün. "] = "İŞTE O AN GELDİ. MATKABI ÇALIŞTIRIR ÇALIŞTIRMAZ, OLABİLDİĞİNCE HIZLI TEKNEYE DÖNÜN. ",
["İşte o! Beni yakalayan orospu çocuğu o!"] = "İŞTE O! BENİ YAKALAYAN OROSPU ÇOCUĞU O!",
["İşte o! Onu kulenin tepesine götürün!"] = "İŞTE O! ONU KULENİN TEPESİNE GÖTÜRÜN!",
["İşte o, tam orada! Şimdi çıkarın onu."] = "İŞTE O, TAM ORADA! ŞİMDİ ÇIKARIN ONU.",
["İşte o. Adını, sosyal güvenlik numarasını, en son ne zaman sıçtığını aldım... Bilişimdeki ekrana bakın. Bulun onu. Burada slotları sevdiği yazıyor, belki oradadır."] = "İŞTE O. ADINI, SOSYAL GÜVENLİK NUMARASINI, EN SON NE ZAMAN SIÇTIĞINI ALDIM... BİLİŞİMDEKİ EKRANA BAKIN. BULUN ONU. BURADA SLOTLARI SEVDİĞİ YAZIYOR, BELKİ ORADADIR.",
["İşte o. Locke."] = "İŞTE O. LOCKE.",
["İşte oldu! Şimdi o Kasa Dairesi'ni açalım!"] = "İŞTE OLDU! ŞİMDİ O KASA DAİRESİ'Nİ AÇALIM!",
["İşte oldu! Şimdi o eseri kapıp hareket edin!"] = "İŞTE OLDU! ŞİMDİ O ESERİ KAPIP HAREKET EDİN!",
["İşte oldu, bir tane daha yeter."] = "İŞTE OLDU, BİR TANE DAHA YETER.",
["İşte oldu, tamamdır! Şimdi içeri girin."] = "İŞTE OLDU, TAMAMDIR! ŞİMDİ İÇERİ GİRİN.",
["İşte oldu, şimdi açalım."] = "İŞTE OLDU, ŞİMDİ AÇALIM.",
["İşte oldu, şimdi sıradakine geçelim."] = "İŞTE OLDU, ŞİMDİ SIRADAKİNE GEÇELİM.",
["İşte oldu."] = "İŞTE OLDU.",
["İşte oldu. Kasa Dairesi açıldı. Hepsi sizin ekip. "] = "İŞTE OLDU. KASA DAİRESİ AÇILDI. HEPSİ SİZİN EKİP. ",
["İşte oldu. Kutuda para!"] = "İŞTE OLDU. KUTUDA PARA!",
["İşte oldu. Çalıyor."] = "İŞTE OLDU. ÇALIYOR.",
["İşte oldu. İyi iş."] = "İŞTE OLDU. İYİ İŞ.",
["İşte oldu. Şimdi maskeni tak."] = "İŞTE OLDU. ŞİMDİ MASKENİ TAK.",
["İşte oldu. Şimdi sadece oradan dışarı göndermelisiniz."] = "İŞTE OLDU. ŞİMDİ SADECE ORADAN DIŞARI GÖNDERMELİSİNİZ.",
["İşte onlar! Wick'in dediği gibi buradalarmış. Bağlayıp minibüsün yanına bırakın. Dönünce Wick o pisliklerin icabına bakar. "] = "İŞTE ONLAR! WICK'İN DEDİĞİ GİBİ BURADALARMIŞ. BAĞLAYIP MİNİBÜSÜN YANINA BIRAKIN. DÖNÜNCE WICK O PİSLİKLERİN İCABINA BAKAR. ",
["İşte orada!"] = "İŞTE ORADA!",
["İşte orada! Ah... Kötü görünüyor dostlar. Hemen çıkarın onu."] = "İŞTE ORADA! AH... KÖTÜ GÖRÜNÜYOR DOSTLAR. HEMEN ÇIKARIN ONU.",
["İşte orada! Alt geçidin hemen ardında!"] = "İŞTE ORADA! ALT GEÇİDİN HEMEN ARDINDA!",
["İşte orada! Ağacı sallayıp hediyeleri düşürün!"] = "İŞTE ORADA! AĞACI SALLAYIP HEDİYELERİ DÜŞÜRÜN!",
["İşte orada! Kapıyı geçip hem BCI başlığını hem yazılımı güvene alın."] = "İŞTE ORADA! KAPIYI GEÇİP HEM BCI BAŞLIĞINI HEM YAZILIMI GÜVENE ALIN.",
["İşte orada! O işe yaramaz bok çuvalını sarsıp uyandırın. Hadi orospu! Uçağım neden yanıyor?"] = "İŞTE ORADA! O İŞE YARAMAZ BOK ÇUVALINI SARSIP UYANDIRIN. HADİ OROSPU! UÇAĞIM NEDEN YANIYOR?",
["İşte orada! Sonunda!"] = "İŞTE ORADA! SONUNDA!",
["İşte orada! Uyandırıp güvenli bir yere götürün. Yakınlarda bir kereste deposu var."] = "İŞTE ORADA! UYANDIRIP GÜVENLİ BİR YERE GÖTÜRÜN. YAKINLARDA BİR KERESTE DEPOSU VAR.",
["İşte orada! Şimdi o kapıyı matkapla açın!"] = "İŞTE ORADA! ŞİMDİ O KAPIYI MATKAPLA AÇIN!",
["İşte orada, beyaz gömlekli Taxman. "] = "İŞTE ORADA, BEYAZ GÖMLEKLİ TAXMAN. ",
["İşte orada, tam ileride. İşinizi yapın millet ama sessizce. Gürültü çıkarsa sizi çabucak çıkarmam gerekecek."] = "İŞTE ORADA, TAM İLERİDE. İŞİNİZİ YAPIN MİLLET AMA SESSİZCE. GÜRÜLTÜ ÇIKARSA SİZİ ÇABUCAK ÇIKARMAM GEREKECEK.",
["İşte orada, üstelik kimse gözlemiyor gibi. Aptal orospu çocukları."] = "İŞTE ORADA, ÜSTELİK KİMSE GÖZLEMİYOR GİBİ. APTAL OROSPU ÇOCUKLARI.",
["İşte orada."] = "İŞTE ORADA.",
["İşte orada. Ama dikkatli basın! O zemin karoları basınca duyarlı. Üstlerine basmayın! Güvenli bir geçiş yolu oluşturmanız gerek! Şuradaki devre kutusunu kullanın."] = "İŞTE ORADA. AMA DİKKATLİ BASIN! O ZEMİN KAROLARI BASINCA DUYARLI. ÜSTLERİNE BASMAYIN! GÜVENLİ BİR GEÇİŞ YOLU OLUŞTURMANIZ GEREK! ŞURADAKİ DEVRE KUTUSUNU KULLANIN.",
["İşte orada. Arka tarafta gibi görünüyor."] = "İŞTE ORADA. ARKA TARAFTA GİBİ GÖRÜNÜYOR.",
["İşte orada. Güzelce istiflenmiş. Siz soyguncu değil misiniz? Soyun hadi!"] = "İŞTE ORADA. GÜZELCE İSTİFLENMİŞ. SİZ SOYGUNCU DEĞİL MİSİNİZ? SOYUN HADİ!",
["İşte orada. Locke."] = "İŞTE ORADA. LOCKE.",
["İşte orada. McKendrick müzesi. İçeride bir yerde paha biçilmez bir elmas var. Alalım."] = "İŞTE ORADA. MCKENDRİCK MÜZESİ. İÇERİDE BİR YERDE PAHA BİÇİLMEZ BİR ELMAS VAR. ALALIM.",
["İşte orada. Moretta. Ama buradan binemeyiz. 3B iskelesine götürün."] = "İŞTE ORADA. MORETTA. AMA BURADAN BİNEMEYİZ. 3B İSKELESİNE GÖTÜRÜN.",
["İşte orada. Söküp her parçasını çıkarın."] = "İŞTE ORADA. SÖKÜP HER PARÇASINI ÇIKARIN.",
["İşte orada. İşinizi yapın millet ama Gage sessizce yapmanızı tercih ediyor. Ana kapı tam karşınızda ama belki başka yollar bulabilirsiniz."] = "İŞTE ORADA. İŞİNİZİ YAPIN MİLLET AMA GAGE SESSİZCE YAPMANIZI TERCİH EDİYOR. ANA KAPI TAM KARŞINIZDA AMA BELKİ BAŞKA YOLLAR BULABİLİRSİNİZ.",
["İşte oradalar, tam Bain'in dediği gibi. Alın onları!"] = "İŞTE ORADALAR, TAM BAIN'İN DEDİĞİ GİBİ. ALIN ONLARI!",
["İşte oradalar, tam Wick'in dediği gibi. Minibüse götürüp şimdilik bağlayın. Giderken yanımızda götüreceğiz. Wick onlarla biraz \"sohbet\" etmek istiyor da. "] = "İŞTE ORADALAR, TAM WICK'İN DEDİĞİ GİBİ. MİNİBÜSE GÖTÜRÜP ŞİMDİLİK BAĞLAYIN. GİDERKEN YANIMIZDA GÖTÜRECEĞİZ. WICK ONLARLA BİRAZ \"SOHBET\" ETMEK İSTİYOR DA. ",
["İşte patlama böyle olur! Pek tatmin edici!"] = "İŞTE PATLAMA BÖYLE OLUR! PEK TATMİN EDİCİ!",
["İşte patlıyor!"] = "İŞTE PATLIYOR!",
["İşte pilot. Tanrım, o yaşlı ayyaş uçak uçurmayı bırak, ayakta zor duruyor. Güvenli bir yere götürün. Helikopteri yola çıkaracağım."] = "İŞTE PİLOT. TANRIM, O YAŞLI AYYAŞ UÇAK UÇURMAYI BIRAK, AYAKTA ZOR DURUYOR. GÜVENLİ BİR YERE GÖTÜRÜN. HELİKOPTERİ YOLA ÇIKARACAĞIM.",
["İşte polisler geliyor!"] = "İŞTE POLİSLER GELİYOR!",
["İşte polisler geliyor."] = "İŞTE POLİSLER GELİYOR.",
["İşte polislerimiz de geldi..."] = "İŞTE POLİSLERİMİZ DE GELDİ...",
["İşte ruh budur!"] = "İŞTE RUH BUDUR!",
["İşte soygun buna denir. Her şeyi almakta iyi iş çıkardınız, çok uğraştınız. Taç da bu durumda ikramiye oldu. Vlad çok mutlu. "] = "İŞTE SOYGUN BUNA DENİR. HER ŞEYİ ALMAKTA İYİ İŞ ÇIKARDINIZ, ÇOK UĞRAŞTINIZ. TAÇ DA BU DURUMDA İKRAMİYE OLDU. VLAD ÇOK MUTLU. ",
["İşte termal kargı. Alın da şu sıçanı güvenli odasından yakarak çıkaralım."] = "İŞTE TERMAL KARGI. ALIN DA ŞU SIÇANI GÜVENLİ ODASINDAN YAKARAK ÇIKARALIM.",
["İşte uçaksavar. Bunu patlatırsak kendimizi de patlatırız. Sistemini kırmamız lazım, o dizüstü bilgisayara erişmemi sağlayın."] = "İŞTE UÇAKSAVAR. BUNU PATLATIRSAK KENDİMİZİ DE PATLATIRIZ. SİSTEMİNİ KIRMAMIZ LAZIM, O DİZÜSTÜ BİLGİSAYARA ERİŞMEMİ SAĞLAYIN.",
["İşte yaptın. Soyguncusun. Kulüptesin. Kulübün avantajlarından biri de bağlantılar. Gage ile tanış. Bize silah bulacak, ganimeti taşımamıza yardım edecek. Onu değerli bir müttefik say. Liman tarafında biraz hırsızlık işini halletmeni istiyor; çok sessiz tut."] = "İŞTE YAPTIN. SOYGUNCUSUN. KULÜPTESİN. KULÜBÜN AVANTAJLARINDAN BİRİ DE BAĞLANTILAR. GAGE İLE TANIŞ. BİZE SİLAH BULACAK, GANİMETİ TAŞIMAMIZA YARDIM EDECEK. ONU DEĞERLİ BİR MÜTTEFİK SAY. LİMAN TARAFINDA BİRAZ HIRSIZLIK İŞİNİ HALLETMENİ İSTİYOR; ÇOK SESSİZ TUT.",
["İşte yine o bitmek bilmeyen, sürekli açlıktan ölüyormuşçasına vahşi bir hırsla tıkınıp karnını doyurma ihtiyacı. Durduğundaysa midende doyurulmayı bekleyen koca bir boşluk açılıyor sanki."] = "İŞTE YİNE O BİTMEK BİLMEYEN, SÜREKLİ AÇLIKTAN ÖLÜYORMUŞÇASINA VAHŞİ BİR HIRSLA TIKINIP KARNINI DOYURMA İHTİYACI. DURDUĞUNDAYSA MİDENDE DOYURULMAYI BEKLEYEN KOCA BİR BOŞLUK AÇILIYOR SANKİ.",
["İşte yüksek teknolojili, yüksek değerli askerî bir canavar. Matkap yolda."] = "İŞTE YÜKSEK TEKNOLOJİLİ, YÜKSEK DEĞERLİ ASKERÎ BİR CANAVAR. MATKAP YOLDA.",
["İşte çalışıyor. Bırakın işini yapsın."] = "İŞTE ÇALIŞIYOR. BIRAKIN İŞİNİ YAPSIN.",
["İşte ödülümüz! Teslimat alanındaki kamyona koyun."] = "İŞTE ÖDÜLÜMÜZ! TESLİMAT ALANINDAKİ KAMYONA KOYUN.",
["İşte ödülümüz. Bain sevinecek. Alıp gidin!"] = "İŞTE ÖDÜLÜMÜZ. BAIN SEVİNECEK. ALIP GİDİN!",
["İşte şimdi oldu hanımlar beyler. Yükü bırakıyorum."] = "İŞTE ŞİMDİ OLDU HANIMLAR BEYLER. YÜKÜ BIRAKIYORUM.",
["İşte şimdi oldu."] = "İŞTE ŞİMDİ OLDU.",
["İşte şu... Aargh, bir boka yaradığı yok. Kalk. Kalk, suka blyad! Ayağa kalk!"] = "İŞTE ŞU... AARGH, BİR BOKA YARADIĞI YOK. KALK. KALK, SUKA BLYAD! AYAĞA KALK!",
["İşte! Alt geçidin hemen ardında!"] = "İŞTE! ALT GEÇİDİN HEMEN ARDINDA!",
["İşte! Neo-2'nin şifresi bu."] = "İŞTE! NEO-2'NİN ŞİFRESİ BU.",
["İşte! Yakıt şimdi tekneye doluyor."] = "İŞTE! YAKIT ŞİMDİ TEKNEYE DOLUYOR.",
["İşte, aradığınız bu olabilir."] = "İŞTE, ARADIĞINIZ BU OLABİLİR.",
["İşte, artık ilerleyin. Kapılar açık."] = "İŞTE, ARTIK İLERLEYİN. KAPILAR AÇIK.",
["İşte, artık şu antika zeminde kocaman bir delik açma vakti, ha?"] = "İŞTE, ARTIK ŞU ANTİKA ZEMİNDE KOCAMAN BİR DELİK AÇMA VAKTİ, HA?",
