["Şarjörü dolu İkincil Silahına geçmek, Birincil Silahının şarjörünü değiştirmekten çoğunlukla daha hızlıdır."] = "ŞARJÖRÜ DOLU İKİNCİL SİLAHINA GEÇMEK, BİRİNCİL SİLAHININ ŞARJÖRÜNÜ DEĞİŞTİRMEKTEN ÇOĞUNLUKLA DAHA HIZLIDIR.",
["Şartröz"] = "ŞARTRÖZ",
["Şebekede biraz dalgalanma görüyorum ama trafoyu patlatmaya yetmez."] = "ŞEBEKEDE BİRAZ DALGALANMA GÖRÜYORUM AMA TRAFOYU PATLATMAYA YETMEZ.",
["Şefe Övgülerimle"] = "ŞEFE ÖVGÜLERİMLE",
["Şefi Öp"] = "ŞEFİ ÖP",
["Şefin ofisini üst katta bulabilirsiniz. Deliller bilgisayarında olmalı."] = "ŞEFİN OFİSİNİ ÜST KATTA BULABİLİRSİNİZ. DELİLLER BİLGİSAYARINDA OLMALI.",
["Şefler kaçıyor."] = "ŞEFLER KAÇIYOR.",
["Şeflerden biri arabayla kaçtı."] = "ŞEFLERDEN BİRİ ARABAYLA KAÇTI.",
["Şehir Merkezi Kalabalığı"] = "ŞEHİR MERKEZİ KALABALIĞI",
["Şehir Merkezi Otoparkı"] = "ŞEHİR MERKEZİ OTOPARKI",
["Şehir Merkezinde Çılgınlık"] = "ŞEHİR MERKEZİNDE ÇILGINLIK",
["Şehir Merkezine İlerliyorum"] = "ŞEHİR MERKEZİNE İLERLİYORUM",
["Şehir Yürüyüşü"] = "ŞEHİR YÜRÜYÜŞÜ",
["Şehir dışında bir iş. Pensacola banliyölerindeki bir kalpazanlık operasyonunun peşindeyiz."] = "ŞEHİR DIŞINDA BİR İŞ. PENSACOLA BANLİYÖLERİNDEKİ BİR KALPAZANLIK OPERASYONUNUN PEŞİNDEYİZ.",
["Şehir dışında hoş küçük bir çiftliğim var. Boris sizi götürecek. Kokain paketlerini çıkarabilir."] = "ŞEHİR DIŞINDA HOŞ KÜÇÜK BİR ÇİFTLİĞİM VAR. BORİS SİZİ GÖTÜRECEK. KOKAİN PAKETLERİNİ ÇIKARABİLİR.",
["Şehir harabe olmasa daha kolay olurdu. Dayanın yeter."] = "ŞEHİR HARABE OLMASA DAHA KOLAY OLURDU. DAYANIN YETER.",
["Şehir merkezinde bir kuyumcu var, oldukça kolay bir hedef. Ama alarm çalarsa polislerin gelmesine hazırlıklı olun."] = "ŞEHİR MERKEZİNDE BİR KUYUMCU VAR, OLDUKÇA KOLAY BİR HEDEF. AMA ALARM ÇALARSA POLİSLERİN GELMESİNE HAZIRLIKLI OLUN.",
["Şehir merkezinde bir üst geçit, stratejik noktalara yerleştirilmiş beş libre C-4 ve kusursuz zamanlamayla GenSec kamyon konvoyunu yolda bırakacağız. Hâlâ sersemlemişken sert vurun. Kamyonlara ve kasalara girin, güzellikleri kaçış şoförüne götürün."] = "ŞEHİR MERKEZİNDE BİR ÜST GEÇİT, STRATEJİK NOKTALARA YERLEŞTİRİLMİŞ BEŞ LİBRE C-4 VE KUSURSUZ ZAMANLAMAYLA GENSEC KAMYON KONVOYUNU YOLDA BIRAKACAĞIZ. HÂLÂ SERSEMLEMİŞKEN SERT VURUN. KAMYONLARA VE KASALARA GİRİN, GÜZELLİKLERİ KAÇIŞ ŞOFÖRÜNE GÖTÜRÜN.",
["Şehir merkezinde birinin önünü kesmeniz gerekiyor. Kendi güvenliğiniz için."] = "ŞEHİR MERKEZİNDE BİRİNİN ÖNÜNÜ KESMENİZ GEREKİYOR. KENDİ GÜVENLİĞİNİZ İÇİN.",
["Şehir merkezinde yeni sevkiyat almış bir kuyumcu var. Vurup kaçmaya var mısınız?"] = "ŞEHİR MERKEZİNDE YENİ SEVKİYAT ALMIŞ BİR KUYUMCU VAR. VURUP KAÇMAYA VAR MISINIZ?",
["Şehir merkezindeki bir kuyumcu yeni mücevher stokladı. O mücevherler bizim olabilir. Var mısınız?"] = "ŞEHİR MERKEZİNDEKİ BİR KUYUMCU YENİ MÜCEVHER STOKLADI. O MÜCEVHERLER BİZİM OLABİLİR. VAR MISINIZ?",
["Şehir merkezindeki bir kuyumcu ziyareti hak ediyor. Size göre mi?"] = "ŞEHİR MERKEZİNDEKİ BİR KUYUMCU ZİYARETİ HAK EDİYOR. SİZE GÖRE Mİ?",
["Şehir merkezindeki bir üst geçit, stratejik biçimde yerleştirilmiş beş libre C-4 ve kusursuz zamanlama sayesinde GenSec kamyonlarından oluşan bir konvoy yolda kaldı. Hâlâ şaşkınken sert vurun. Kamyonları ve kasaları açıp güzelim ganimeti kaçış sürücüsüne götürün."] = "ŞEHİR MERKEZİNDEKİ BİR ÜST GEÇİT, STRATEJİK BİÇİMDE YERLEŞTİRİLMİŞ BEŞ LİBRE C-4 VE KUSURSUZ ZAMANLAMA SAYESİNDE GENSEC KAMYONLARINDAN OLUŞAN BİR KONVOY YOLDA KALDI. HÂLÂ ŞAŞKINKEN SERT VURUN. KAMYONLARI VE KASALARI AÇIP GÜZELİM GANİMETİ KAÇIŞ SÜRÜCÜSÜNE GÖTÜRÜN.",
["Şehir merkezindeki yeni kuyumcu mücevher dolu. Bizim olabilirler. Ziyaret etmek ister misiniz?"] = "ŞEHİR MERKEZİNDEKİ YENİ KUYUMCU MÜCEVHER DOLU. BİZİM OLABİLİRLER. ZİYARET ETMEK İSTER MİSİNİZ?",
["Şehir yukarıdan güzel görünüyor."] = "ŞEHİR YUKARIDAN GÜZEL GÖRÜNÜYOR.",
["Şehirli Kung Fu Ustası çatılarda ilerlerken sirenler uluyordu. Zaman daralıyordu. Kalp atışları kulaklarında sabit bir ritim tutuyor, beyaz spor ayakkabılarının her adımı ritme ekleniyordu. Önünde binalar arasında büyük bir boşluk vardı. Karşı tarafta, bir bacadan sarkan, alıp getirmesi için gönderildiği ödül duruyordu. Atlayışa hazırlandı. Turna usulü havalanma zamanı..."] = "ŞEHİRLİ KUNG FU USTASI ÇATILARDA İLERLERKEN SİRENLER ULUYORDU. ZAMAN DARALIYORDU. KALP ATIŞLARI KULAKLARINDA SABİT BİR RİTİM TUTUYOR, BEYAZ SPOR AYAKKABILARININ HER ADIMI RİTME EKLENİYORDU. ÖNÜNDE BİNALAR ARASINDA BÜYÜK BİR BOŞLUK VARDI. KARŞI TARAFTA, BİR BACADAN SARKAN, ALIP GETİRMESİ İÇİN GÖNDERİLDİĞİ ÖDÜL DURUYORDU. ATLAYIŞA HAZIRLANDI. TURNA USULÜ HAVALANMA ZAMANI...",
["Şehre yeni döndüm, Rus (serseriler) görüyorum. Dmitri'nin adamları, benim bölgemde. Buna KATLANAMAM!"] = "ŞEHRE YENİ DÖNDÜM, RUS (SERSERİLER) GÖRÜYORUM. DMİTRİ'NİN ADAMLARI, BENİM BÖLGEMDE. BUNA KATLANAMAM!",
["Şehrin En İyileri"] = "ŞEHRİN EN İYİLERİ",
["Şehrin Öbür Ucuna Trafik"] = "ŞEHRİN ÖBÜR UCUNA TRAFİK",
["Şeker Pembesi"] = "ŞEKER PEMBESİ",
["Şeker mi şaka mı, kokla bakalım ayağımı. Ver bir şey, sokakta satayım. Vermezsen de takmam ben; yeter ki donunla pişirme sen."] = "ŞEKER Mİ ŞAKA MI, KOKLA BAKALIM AYAĞIMI. VER BİR ŞEY, SOKAKTA SATAYIM. VERMEZSEN DE TAKMAM BEN; YETER Kİ DONUNLA PİŞİRME SEN.",
["Şeker ya da Şaka!"] = "ŞEKER YA DA ŞAKA!",
["Şeker ya da şaka"] = "ŞEKER YA DA ŞAKA",
["Şeker, Domuz Yağı ve Akrepler"] = "ŞEKER, DOMUZ YAĞI VE AKREPLER",
["Şema buldunuz mu?"] = "ŞEMA BULDUNUZ MU?",
["Şemaya bakıp doğru kabloları bulun!"] = "ŞEMAYA BAKIP DOĞRU KABLOLARI BULUN!",
["Şerif Yıldızı"] = "ŞERİF YILDIZI",
["Şerif Yıldızı gerekiyor"] = "ŞERİF YILDIZI GEREKİYOR",
["Şerif Yıldızı yapılıyor"] = "ŞERİF YILDIZI YAPILIYOR",
["Şey yapsak mı... Onu indirebilir miyim?"] = "ŞEY YAPSAK MI... ONU İNDİREBİLİR MİYİM?",
["Şey, Barney şu an müsait değil. Mesajınızı alabilir miyim?"] = "ŞEY, BARNEY ŞU AN MÜSAİT DEĞİL. MESAJINIZI ALABİLİR MİYİM?",
["Şey, alo?"] = "ŞEY, ALO?",
["Şey, bakın... Durumu kontrol etmeleri için oraya birkaç adam göndereceğim."] = "ŞEY, BAKIN... DURUMU KONTROL ETMELERİ İÇİN ORAYA BİRKAÇ ADAM GÖNDERECEĞİM.",
["Şey, bu açık mı? Sizi kapılardan geçirebilirim ama önce 4 haneli şifre bulmalısınız. Benimkini kullanamayız, yoksa benim olduğumu anlarlar."] = "ŞEY, BU AÇIK MI? SİZİ KAPILARDAN GEÇİREBİLİRİM AMA ÖNCE 4 HANELİ ŞİFRE BULMALISINIZ. BENİMKİNİ KULLANAMAYIZ, YOKSA BENİM OLDUĞUMU ANLARLAR.",
["Şey, doğru okuyorsam... Şey..."] = "ŞEY, DOĞRU OKUYORSAM... ŞEY...",
["Şey, ekip, üzerinize ÇOK büyük bir ateş gücü geliyor. Hemen minibüse gitmeniz gerekiyor!"] = "ŞEY, EKİP, ÜZERİNİZE ÇOK BÜYÜK BİR ATEŞ GÜCÜ GELİYOR. HEMEN MİNİBÜSE GİTMENİZ GEREKİYOR!",
["Şey, eski akrabalara aitti, aile yadigârları, bilirsiniz?"] = "ŞEY, ESKİ AKRABALARA AİTTİ, AİLE YADİGÂRLARI, BİLİRSİNİZ?",
["Şey, evet. Burada her şey güllük gülistanlık. Sadece... rutin kontroller."] = "ŞEY, EVET. BURADA HER ŞEY GÜLLÜK GÜLİSTANLIK. SADECE... RUTİN KONTROLLER.",
["Şey, her şey yolunda mı? Müzayedeyi başlatmak üzereyim ama bir talep görüyorum."] = "ŞEY, HER ŞEY YOLUNDA MI? MÜZAYEDEYİ BAŞLATMAK ÜZEREYİM AMA BİR TALEP GÖRÜYORUM.",
["Şey, hmm. Bana Jiu Feng diyebilirsiniz. Sokaktaki söylentiye göre Payday Gang iş yapılacak sağlam bir ekip, değil mi? Bir de her zaman daha fazla... tedarikçiye ihtiyacınız varmış. Hizmetlerim ilginizi çekebilir. Belki... uzun vadeli bir şey bile ayarlanabilir. Düşünün; yakında konuşuruz, tamam mı?"] = "ŞEY, HMM. BANA JIU FENG DİYEBİLİRSİNİZ. SOKAKTAKİ SÖYLENTİYE GÖRE PAYDAY GANG İŞ YAPILACAK SAĞLAM BİR EKİP, DEĞİL Mİ? BİR DE HER ZAMAN DAHA FAZLA... TEDARİKÇİYE İHTİYACINIZ VARMIŞ. HİZMETLERİM İLGİNİZİ ÇEKEBİLİR. BELKİ... UZUN VADELİ BİR ŞEY BİLE AYARLANABİLİR. DÜŞÜNÜN; YAKINDA KONUŞURUZ, TAMAM MI?",
["Şey, kontrol, yine sıçıp batırdım. Tekrar ediyorum: sıçıp batırdım. Yeniden deniyorum."] = "ŞEY, KONTROL, YİNE SIÇIP BATIRDIM. TEKRAR EDİYORUM: SIÇIP BATIRDIM. YENİDEN DENİYORUM.",
["Şey, kusura bakmayın, ilk günüm. Ne lazım?"] = "ŞEY, KUSURA BAKMAYIN, İLK GÜNÜM. NE LAZIM?",
["Şey, numara şuydu..."] = "ŞEY, NUMARA ŞUYDU...",
["Şey, o konumdan birkaç 911 araması görüyorum. Hazır olun!"] = "ŞEY, O KONUMDAN BİRKAÇ 911 ARAMASI GÖRÜYORUM. HAZIR OLUN!",
["Şey, olumsuz Broadsword. Çatı yaklaşması uygun değil. Tamam."] = "ŞEY, OLUMSUZ BROADSWORD. ÇATI YAKLAŞMASI UYGUN DEĞİL. TAMAM.",
["Şey, pardon, yanlış numara..."] = "ŞEY, PARDON, YANLIŞ NUMARA...",
["Şey, sadece... Evet, bir şey sıçtı. Düzeltin, millet."] = "ŞEY, SADECE... EVET, BİR ŞEY SIÇTI. DÜZELTİN, MİLLET.",
["Şey, siktir... Sıyırdık geçtik. Bir tur daha atıyorum."] = "ŞEY, SİKTİR... SIYIRDIK GEÇTİK. BİR TUR DAHA ATIYORUM.",
["Şey, umarım doğru anlamışımdır..."] = "ŞEY, UMARIM DOĞRU ANLAMIŞIMDIR...",
["Şey... Alan... Watson. Tetikte olun palyaçolar. GenSec geliyor."] = "ŞEY... ALAN... WATSON. TETİKTE OLUN PALYAÇOLAR. GENSEC GELİYOR.",
["Şey... Belki de Alex'i tutmalıydık."] = "ŞEY... BELKİ DE ALEX'İ TUTMALIYDIK.",
["Şey... Bu... Beklediğimden çok prototip var... Kaç tane bunlar..."] = "ŞEY... BU... BEKLEDİĞİMDEN ÇOK PROTOTİP VAR... KAÇ TANE BUNLAR...",
["Şey... David, şey, Jones. Millet, misafirleriniz olacak."] = "ŞEY... DAVİD, ŞEY, JONES. MİLLET, MİSAFİRLERİNİZ OLACAK.",
["Şey... Duruma göre hareket edelim."] = "ŞEY... DURUMA GÖRE HAREKET EDELİM.",
["Şey... Ekip... Asansörler hareket ediyor. Misafir bekleyin."] = "ŞEY... EKİP... ASANSÖRLER HAREKET EDİYOR. MİSAFİR BEKLEYİN.",
["Şey... Evet... Telsizleri çalışmıyor. Güneş lekesi faaliyeti."] = "ŞEY... EVET... TELSİZLERİ ÇALIŞMIYOR. GÜNEŞ LEKESİ FAALİYETİ.",
["Şey... Fikrinizi değiştiremem mi? Ya siz... Gözlerime bakın!"] = "ŞEY... FİKRİNİZİ DEĞİŞTİREMEM Mİ? YA SİZ... GÖZLERİME BAKIN!",
["Şey... Kazlar yüzünden... iptal ediyorum. Yeniden dönüyorum."] = "ŞEY... KAZLAR YÜZÜNDEN... İPTAL EDİYORUM. YENİDEN DÖNÜYORUM.",
["Şey... Mantıklı sanırım. Ben de öyle yapabilirim."] = "ŞEY... MANTIKLI SANIRIM. BEN DE ÖYLE YAPABİLİRİM.",
["Şey... Polis telsizimdir. Kapatayım. Polis kilometrelerce uzakta."] = "ŞEY... POLİS TELSİZİMDİR. KAPATAYIM. POLİS KİLOMETRELERCE UZAKTA.",
["Şey... Tamam o zaman."] = "ŞEY... TAMAM O ZAMAN.",
["Şey... Tamam, eşyaları parçala. Anladım."] = "ŞEY... TAMAM, EŞYALARI PARÇALA. ANLADIM.",
["Şey... Yok, işe yaramadı. Başkasını deneyin."] = "ŞEY... YOK, İŞE YARAMADI. BAŞKASINI DENEYİN.",
["Şey... Şu kapıda bana yardım edin millet."] = "ŞEY... ŞU KAPIDA BANA YARDIM EDİN MİLLET.",
["Şeytan Gibi Bir İş"] = "ŞEYTAN GİBİ BİR İŞ",
["Şeytani Bir Hız mı Çektin?"] = "ŞEYTANİ BİR HIZ MI ÇEKTİN?",
["Şeytani Olmak"] = "ŞEYTANİ OLMAK",
["Şeytanlar da iblisler de bu maskeyi takan soyguncunun ihtişamını gördüklerinde hayranlıkla titreyecek."] = "ŞEYTANLAR DA İBLİSLER DE BU MASKEYİ TAKAN SOYGUNCUNUN İHTİŞAMINI GÖRDÜKLERİNDE HAYRANLIKLA TİTREYECEK.",
["Şeytanın Kucak Köpeği"] = "ŞEYTANIN KUCAK KÖPEĞİ",
["Şeytanın yaptığı en büyük ikinci numara, kocaman boynuzlu ve kırmızı tenli bir iblis olarak resmedilmesiydi. Artık metroda telefonunun hoparlöründen müzik dinleyen kişinin gerçekte kim olduğunu kimse bilmiyor."] = "ŞEYTANIN YAPTIĞI EN BÜYÜK İKİNCİ NUMARA, KOCAMAN BOYNUZLU VE KIRMIZI TENLİ BİR İBLİS OLARAK RESMEDİLMESİYDİ. ARTIK METRODA TELEFONUNUN HOPARLÖRÜNDEN MÜZİK DİNLEYEN KİŞİNİN GERÇEKTE KİM OLDUĞUNU KİMSE BİLMİYOR.",
["Şiddet dolu oyunlar Wolf’u soygun havasına sokar. Kan, vahşet ve katliam ne kadar fazlaysa o kadar iyi. Tepkini ve hızını sınayan oyunları tercih eder. Neredeyse sonsuz düşman sürüsüne karşı hayatta kalmak için her saniyenin önemli olduğu oyunları."] = "ŞİDDET DOLU OYUNLAR WOLF’U SOYGUN HAVASINA SOKAR. KAN, VAHŞET VE KATLİAM NE KADAR FAZLAYSA O KADAR İYİ. TEPKİNİ VE HIZINI SINAYAN OYUNLARI TERCİH EDER. NEREDEYSE SONSUZ DÜŞMAN SÜRÜSÜNE KARŞI HAYATTA KALMAK İÇİN HER SANİYENİN ÖNEMLİ OLDUĞU OYUNLARI.",
["Şiddet her zaman bir seçenektir. Bununla şiddeti daha uzun süre sürdürebilirsiniz."] = "ŞİDDET HER ZAMAN BİR SEÇENEKTİR. BUNUNLA ŞİDDETİ DAHA UZUN SÜRE SÜRDÜREBİLİRSİNİZ.",
["Şiddet kısmını siz üstlenin, tamam mı? Üniformam sayesinde aralarına karışıp çatışmadan uzak kalabilirim."] = "ŞİDDET KISMINI SİZ ÜSTLENİN, TAMAM MI? ÜNİFORMAM SAYESİNDE ARALARINA KARIŞIP ÇATIŞMADAN UZAK KALABİLİRİM.",
["Şifacı"] = "ŞİFACI",
["Şifacının Sandığı"] = "ŞİFACININ SANDIĞI",
["Şifalı Eller"] = "ŞİFALI ELLER",
["Şifre Deng'in masaj odasındaki bir kasada."] = "ŞİFRE DENG'İN MASAJ ODASINDAKİ BİR KASADA.",
["Şifre belirli aralıklarla yenileniyor. Geçerli şifreyi bul."] = "ŞİFRE BELİRLİ ARALIKLARLA YENİLENİYOR. GEÇERLİ ŞİFREYİ BUL.",
["Şifre bu. Geri dönüp kapıyı açın."] = "ŞİFRE BU. GERİ DÖNÜP KAPIYI AÇIN.",
["Şifre de... 1138!"] = "ŞİFRE DE... 1138!",
["Şifre ekranda olmalı. Alıp Kasa Dairesi'ni açmaya gidin."] = "ŞİFRE EKRANDA OLMALI. ALIP KASA DAİRESİ'Nİ AÇMAYA GİDİN.",
["Şifre ekranda olmalı. Alıp kasa dairesini açın."] = "ŞİFRE EKRANDA OLMALI. ALIP KASA DAİRESİNİ AÇIN.",
["Şifre engellendi, onu unutun. Başka bir çözüm gerekecek."] = "ŞİFRE ENGELLENDİ, ONU UNUTUN. BAŞKA BİR ÇÖZÜM GEREKECEK.",
