["Şu odanın gidişine bakın! Başardık be!"] = "ŞU ODANIN GİDİŞİNE BAKIN! BAŞARDIK BE!",
["Şu oluk ganimeti şuranın arka odalarına taşıyabilir..."] = "ŞU OLUK GANİMETİ ŞURANIN ARKA ODALARINA TAŞIYABİLİR...",
