["Şu plakaya bakın! Bahse girerim pazarlamacı kadının arabası. Biraz çizerseniz araba alarmı onu dışarı çıkarır."] = "ŞU PLAKAYA BAKIN! BAHSE GİRERİM PAZARLAMACI KADININ ARABASI. BİRAZ ÇİZERSENİZ ARABA ALARMI ONU DIŞARI ÇIKARIR.",
["Şu platformu hareket ettirelim! Pencerenin yanındaki ışıkla bağlantımıza işaret verin."] = "ŞU PLATFORMU HAREKET ETTİRELİM! PENCERENİN YANINDAKİ IŞIKLA BAĞLANTIMIZA İŞARET VERİN.",
["Şu renkli tankları görüyor musunuz? Bu boruları, petrol numunemize uygun olana bağlamalıyız. Bağlantıyı kurup tankın kolunu çekin. Ben gemimizi yerine getiririm."] = "ŞU RENKLİ TANKLARI GÖRÜYOR MUSUNUZ? BU BORULARI, PETROL NUMUNEMİZE UYGUN OLANA BAĞLAMALIYIZ. BAĞLANTIYI KURUP TANKIN KOLUNU ÇEKİN. BEN GEMİMİZİ YERİNE GETİRİRİM.",
["Şu sandık zımbırtısını açmalısınız."] = "ŞU SANDIK ZIMBIRTISINI AÇMALISINIZ.",
["Şu sandıklar Commissar'ın diğer pis inlerine gidecek. Etiketlerini alın ve şu kod okuyucuda kontrol edin."] = "ŞU SANDIKLAR COMMİSSAR'IN DİĞER PİS İNLERİNE GİDECEK. ETİKETLERİNİ ALIN VE ŞU KOD OKUYUCUDA KONTROL EDİN.",
["Şu sandıkları görüyor musunuz? Doğrudan Commissar'ın bulunduğu yere gönderilmek üzereler. Etiketlerini alıp şuradaki okuyucuda kontrol edin. Commissar'ın tam yerini böyle öğrenebiliriz."] = "ŞU SANDIKLARI GÖRÜYOR MUSUNUZ? DOĞRUDAN COMMİSSAR'IN BULUNDUĞU YERE GÖNDERİLMEK ÜZERELER. ETİKETLERİNİ ALIP ŞURADAKİ OKUYUCUDA KONTROL EDİN. COMMİSSAR'IN TAM YERİNİ BÖYLE ÖĞRENEBİLİRİZ.",
["Şu sandıkların arkası olur. Şimdi diğer adamı al. Bir Ceset Torbası daha almayı unutma."] = "ŞU SANDIKLARIN ARKASI OLUR. ŞİMDİ DİĞER ADAMI AL. BİR CESET TORBASI DAHA ALMAYI UNUTMA.",
["Şu sarhoş piçe bakın. Suratına sıçası geliyor insanın. İşe yaramaz orospu...!"] = "ŞU SARHOŞ PİÇE BAKIN. SURATINA SIÇASI GELİYOR İNSANIN. İŞE YARAMAZ OROSPU...!",
["Şu sayacı görüyor musunuz? Ganimeti güvenceye almak istiyorsanız acele edin!"] = "ŞU SAYACI GÖRÜYOR MUSUNUZ? GANİMETİ GÜVENCEYE ALMAK İSTİYORSANIZ ACELE EDİN!",
["Şu sersem herifler laboratuvarın elektriğini kesti. Duvardaki kutuyu bulup yeniden açın."] = "ŞU SERSEM HERİFLER LABORATUVARIN ELEKTRİĞİNİ KESTİ. DUVARDAKİ KUTUYU BULUP YENİDEN AÇIN.",
["Şu ses kayıt cihazını bulun millet."] = "ŞU SES KAYIT CİHAZINI BULUN MİLLET.",
["Şu sevkiyat manifestosuna erişelim, olur mu?"] = "ŞU SEVKİYAT MANİFESTOSUNA ERİŞELİM, OLUR MU?",
