["Şu sunucu odasının kapısını açın!"] = "ŞU SUNUCU ODASININ KAPISINI AÇIN!",
["Şu suyu yeniden akıtalım!"] = "ŞU SUYU YENİDEN AKITALIM!",
["Şu sıralar Washington'da bir sürü bok dönüyor."] = "ŞU SIRALAR WASHINGTON'DA BİR SÜRÜ BOK DÖNÜYOR.",
["Şu sıçan piçin sizin gibi dürüst, onurlu belalılardan talepte bulunabildiği nasıl bir dünyada yaşıyoruz? Ama dediğini yapsanız iyi olur."] = "ŞU SIÇAN PİÇİN SİZİN GİBİ DÜRÜST, ONURLU BELALILARDAN TALEPTE BULUNABİLDİĞİ NASIL BİR DÜNYADA YAŞIYORUZ? AMA DEDİĞİNİ YAPSANIZ İYİ OLUR.",
["Şu tarete bakın! Herifler gelirse aklınızda olsun."] = "ŞU TARETE BAKIN! HERİFLER GELİRSE AKLINIZDA OLSUN.",
["Şu tareti görüyor musunuz? İşler ters giderse işe yarayabilir."] = "ŞU TARETİ GÖRÜYOR MUSUNUZ? İŞLER TERS GİDERSE İŞE YARAYABİLİR.",
["Şu tekneyi suya indirip sızdırıyor mu öğrenelim."] = "ŞU TEKNEYİ SUYA İNDİRİP SIZDIRIYOR MU ÖĞRENELİM.",
["Şu tesisatçılar gidince partiyi gerçekten başlatabiliriz."] = "ŞU TESİSATÇILAR GİDİNCE PARTİYİ GERÇEKTEN BAŞLATABİLİRİZ.",
["Şu teçhizatınızı seçin artık! O Domuzcuk Kumbarası'nı bulmak istiyorum!"] = "ŞU TEÇHİZATINIZI SEÇİN ARTIK! O DOMUZCUK KUMBARASI'NI BULMAK İSTİYORUM!",
["Şu topu doğru yöne çevirmek lazım."] = "ŞU TOPU DOĞRU YÖNE ÇEVİRMEK LAZIM.",
["Şu ufak uyuşturucu alışverişi tiyatrosunda rollerimize girelim..."] = "ŞU UFAK UYUŞTURUCU ALIŞVERİŞİ TİYATROSUNDA ROLLERİMİZE GİRELİM...",
