["Şu video oyunu denenlerden niye olmasın?"] = "ŞU VİDEO OYUNU DENENLERDEN NİYE OLMASIN?",
["Şu vincin yanında bir şey oluyor. Polisler oradan da gelecek."] = "ŞU VİNCİN YANINDA BİR ŞEY OLUYOR. POLİSLER ORADAN DA GELECEK.",
["Şu vinç... polisler onunla size ulaşmak için yeni bir yol açıyor!"] = "ŞU VİNÇ... POLİSLER ONUNLA SİZE ULAŞMAK İÇİN YENİ BİR YOL AÇIYOR!",
["Şu zemini açmanız gerekiyor dostlar!"] = "ŞU ZEMİNİ AÇMANIZ GEREKİYOR DOSTLAR!",
["Şu zımbırtıya yakıt doldurmanız gerekiyor. İşe koyulun. "] = "ŞU ZIMBIRTIYA YAKIT DOLDURMANIZ GEREKİYOR. İŞE KOYULUN. ",
["Şu zımbırtıyı ana merkezdeki taşıma bandına atmak iyi fikir olabilir. Makineler sizin yerinize girişe taşısın, değil mi?"] = "ŞU ZIMBIRTIYI ANA MERKEZDEKİ TAŞIMA BANDINA ATMAK İYİ FİKİR OLABİLİR. MAKİNELER SİZİN YERİNİZE GİRİŞE TAŞISIN, DEĞİL Mİ?",
["Şu zımbırtıyı minibüse çıkarın, tamam mı?"] = "ŞU ZIMBIRTIYI MİNİBÜSE ÇIKARIN, TAMAM MI?",
["Şu zımbırtıyı yoldan çekin!"] = "ŞU ZIMBIRTIYI YOLDAN ÇEKİN!",
["Şu çatılardan birinden iyi bir koruma ateşi sağlayabilirsiniz."] = "ŞU ÇATILARDAN BİRİNDEN İYİ BİR KORUMA ATEŞİ SAĞLAYABİLİRSİNİZ.",
["Şu çiftlik evine girin. Dizüstü bilgisayar orada bir yerde olacak."] = "ŞU ÇİFTLİK EVİNE GİRİN. DİZÜSTÜ BİLGİSAYAR ORADA BİR YERDE OLACAK.",
["Şu çirkin bok yığını kim?... Ne oluyor lan... o da...!? Ah! Şimdi onunla uğraşacak vakit yok! Çıkın oradan! Acele edin!"] = "ŞU ÇİRKİN BOK YIĞINI KİM?... NE OLUYOR LAN... O DA...!? AH! ŞİMDİ ONUNLA UĞRAŞACAK VAKİT YOK! ÇIKIN ORADAN! ACELE EDİN!",
["Şu çöp konteyneri nasıl?"] = "ŞU ÇÖP KONTEYNERİ NASIL?",
["Şu üst üste dizili sandıklar Commissar'a gönderilecek. Etiketlere bakın. Doğru etiketi kod okuyucuya götürün, bizi doğrudan Commissar'a ulaştırmalı."] = "ŞU ÜST ÜSTE DİZİLİ SANDIKLAR COMMİSSAR'A GÖNDERİLECEK. ETİKETLERE BAKIN. DOĞRU ETİKETİ KOD OKUYUCUYA GÖTÜRÜN, BİZİ DOĞRUDAN COMMİSSAR'A ULAŞTIRMALI.",
["Şu ışıklar. Bir tür gösterge. Etrafa bakın, bir şeyle eşleştirebiliyor musunuz görün."] = "ŞU IŞIKLAR. BİR TÜR GÖSTERGE. ETRAFA BAKIN, BİR ŞEYLE EŞLEŞTİREBİLİYOR MUSUNUZ GÖRÜN.",
["Şu ışıkları görüyor musunuz? Bir şeye bağlı olduklarından eminim."] = "ŞU IŞIKLARI GÖRÜYOR MUSUNUZ? BİR ŞEYE BAĞLI OLDUKLARINDAN EMİNİM.",
["Şu şalteri indirin hödükler."] = "ŞU ŞALTERİ İNDİRİN HÖDÜKLER.",
["Şu şeyin vidalarını sökün."] = "ŞU ŞEYİN VİDALARINI SÖKÜN.",
["Şuna bakar mısınız!? Başardık, ekip. Başardık."] = "ŞUNA BAKAR MISINIZ!? BAŞARDIK, EKİP. BAŞARDIK.",
["Şuna bakın! Buradan hiç çıkamayacağım sanıyordum. Beni çözer misiniz lütfen?"] = "ŞUNA BAKIN! BURADAN HİÇ ÇIKAMAYACAĞIM SANIYORDUM. BENİ ÇÖZER MİSİNİZ LÜTFEN?",
["Şuna bakın! GenSec'in zırhlı para nakil aracı! Bu işten eve biraz nakit götürmek istiyorsanız soyabilirsiniz!"] = "ŞUNA BAKIN! GENSEC'İN ZIRHLI PARA NAKİL ARACI! BU İŞTEN EVE BİRAZ NAKİT GÖTÜRMEK İSTİYORSANIZ SOYABİLİRSİNİZ!",
["Şuna bakın! Kutunun kepenkleri bozuldu! Laboratuvardaki elektrik karmaşası bütün yerleşkeyi etkilemiş olmalı. Güzel tesadüfler!"] = "ŞUNA BAKIN! KUTUNUN KEPENKLERİ BOZULDU! LABORATUVARDAKİ ELEKTRİK KARMAŞASI BÜTÜN YERLEŞKEYİ ETKİLEMİŞ OLMALI. GÜZEL TESADÜFLER!",
["Şuna bakın! Şimdi kalıp hepsinin yandığından emin olun!"] = "ŞUNA BAKIN! ŞİMDİ KALIP HEPSİNİN YANDIĞINDAN EMİN OLUN!",
["Şuna bakın, IRS'le büyük bir şirketin kirli anlaşmasını bozuyoruz. Robin Hood gibiyiz!"] = "ŞUNA BAKIN, IRS'LE BÜYÜK BİR ŞİRKETİN KİRLİ ANLAŞMASINI BOZUYORUZ. ROBİN HOOD GİBİYİZ!",
["Şuna bakın, zenginim!"] = "ŞUNA BAKIN, ZENGİNİM!",
["Şuna bakın. Durun! O yer karoları. Basınca duyarlılar, üstlerine basmayın. Kapının yanındaki devre kutusunun sistemini kırın, güvenli bir geçiş yolu açar."] = "ŞUNA BAKIN. DURUN! O YER KAROLARI. BASINCA DUYARLILAR, ÜSTLERİNE BASMAYIN. KAPININ YANINDAKİ DEVRE KUTUSUNUN SİSTEMİNİ KIRIN, GÜVENLİ BİR GEÇİŞ YOLU AÇAR.",
["Şuna bakın. Herifler bizi aptal sanıyor olmalı, bu kadar düşük teklif verdiklerine göre. Bakalım ne kadar yükseltecekler, ha?"] = "ŞUNA BAKIN. HERİFLER BİZİ APTAL SANIYOR OLMALI, BU KADAR DÜŞÜK TEKLİF VERDİKLERİNE GÖRE. BAKALIM NE KADAR YÜKSELTECEKLER, HA?",
["Şuna bakın. Yukarıda bir sürü zengin keyif çatıyor."] = "ŞUNA BAKIN. YUKARIDA BİR SÜRÜ ZENGİN KEYİF ÇATIYOR.",
["Şunları atlatamıyorum amına koyayım!"] = "ŞUNLARI ATLATAMIYORUM AMINA KOYAYIM!",
